    std::uint64_t *aTwistWandererUpdateSaltF = pWorkSpace->mDomainBundle.mTwistSalts.mWandererUpdate.mSaltF;
    const std::uint64_t &aTwistDomainWordIngress = pWorkSpace->mDomainBundle.mTwistConstants.mIngress;
