            //
            aOrbiterB = ((aWandererH + RotL64(aScatter, 47U)) + RotL64(aCarry, 35U)) + 0xFB262AEFBCAE1504ULL;
            aOrbiterC = ((aWandererG + RotL64(aPrevious, 23U)) + RotL64(aCarry, 27U)) + 0xA252DB4A36D6BBB3ULL;
