            aOrbiterD = (aWandererK + RotL64(aIngress, 34U)) + 0xDFDC29B68295B234ULL;
            aOrbiterA = ((aWandererE + RotL64(aScatter, 43U)) + 0xABB46128C81985F9ULL) + aTwistOrbiterAssignSaltC[(((255U - aIndex) + 133U)) & S_SALT1];
            aOrbiterE = ((aWandererF + RotL64(aPrevious, 11U)) + 0x26ACA2815877CB62ULL) + aTwistOrbiterAssignSaltD[(((255U - aIndex) + 65U)) & S_SALT1];
            aOrbiterH = ((aWandererI + RotL64(aIngress, 19U)) + RotL64(aCarry, 57U)) + 0x8E4AB08D2831ACD9ULL;
            aOrbiterG = (aWandererC + RotL64(aCross, 30U)) + 0x75D2DE215872B914ULL;
            aOrbiterF = (aWandererA + RotL64(aIngress, 3U)) + 0xD8B1F37734277F0CULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x5E34DA8FD7F57CACULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterB) ^ 0x12046E50185CD8CCULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 157U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x690A324B272EF6F3ULL), 19U);
