            aOrbiterD = (aOrbiterD + aOrbiterA) + 0xA87E648BF9175E91ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x331AE1C0B82A8FDFULL;
            aOrbiterC = RotL64((aOrbiterC * 0xA2D41F5063F113F1ULL), 13U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x2D207F7DFC0C6EECULL) + aTwistOrbiterUpdateSaltD[(((255U - aIndex) + 235U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0x5F4A8EF262A58762ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xE32573B74B28A82DULL), 3U);
