            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0x6A739F204687E8F9ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 23U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x506F17E3A2C95975ULL;
