            aOrbiterH = ((aWandererG + RotL64(aIngress, 27U)) + 0x837A9C50FB6E993EULL) + aTwistOrbiterAssignSaltC[(((255U - aIndex) + 75U)) & S_SALT1];
            aOrbiterC = ((aWandererC + RotL64(aCross, 56U)) + RotL64(aCarry, 53U)) + 0x8F1035D4C34529ECULL;
