            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0xA645E3CE0A4C4CA7ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterI) ^ 0xCE1576BD8E5977C7ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 59U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x41423DD6CE74A67FULL), 29U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x37786EB4CCBE65F8ULL;
