            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0xCD2D856CE745B885ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 174U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterH) ^ 0x0E736663EC4082D8ULL) ^ aKeyRotateAOrbiterUpdateSaltB[(((255U - aIndex) + 245U)) & S_SALT1];
