            aOrbiterE = ((aOrbiterE ^ aOrbiterJ) ^ 0x90A9D7553D9C869CULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((255U - aIndex) + 31U)) & S_SALT1];
