            aOrbiterA = ((aWandererC + RotL64(aPrevious, 44U)) + 0x2C3169B49217C530ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 151U)) & S_SALT1];
            aOrbiterI = (aWandererD + RotL64(aScatter, 11U)) + 0xF8AC9DF1BF8C7672ULL;
            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0x768E47C69D6BC5FCULL) + aKeyRotateAOrbiterUpdateSaltA[(((255U - aIndex) + 89U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0xF65406610CFCCF65ULL;
