            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0xD3767B54A1AEF0DAULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x8DEB08288AAC3DA5ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x8CD12DE997C5E631ULL), 5U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x689CB9DC8D6EC6EAULL;
