            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xDF5FA41FA981AF41ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterF) ^ 0x80F3338C4686AF67ULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 7U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xCB7A76536840F37BULL), 47U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x92971FB36775149FULL;
