            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0xDBCEB63DB5612B03ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0xF1C8B3AA7431648DULL;
